import React from 'react';

const StartPauseReset = ({onStart, onPause, onReset}) => {

  const buttonList = [
    { name: 'start', id: 'start', function: onStart },
    { name: 'pause', id: 'pause', function: onPause },
    { name: 'reset', id: 'reset', function: onReset },
  ];

  return (
    <div className="grid grid-cols-3 gap-10 place-items-center width-80">
      {buttonList.map((btn) => (
        <button
          key={btn.id}
          className="w-full 

          whitespace-nowrap 
          p-3 sm:p-2 
          text-white 
          shadow-sm text-xl sm:text-sm md:text-md bg-white bg-opacity-20 rounded-lg hover:bg-opacity-5 hover:scale-105 transition duration-100 ease-in-out cursor-pointer"
          onClick={btn.function}
        >
          {' '}
          {btn.name}
        </button>
      ))}
    </div>
  );
};

export default StartPauseReset;
